class PS2Runtime
{
public:
    struct IoPaths
    {
        std::filesystem::path elfPath;
        std::filesystem::path elfDirectory;
        std::filesystem::path hostRoot;
        std::filesystem::path cdRoot;
        std::filesystem::path mcRoot;
        std::filesystem::path cdImage;
    };

    PS2Runtime();
    ~PS2Runtime();

    bool initialize(const char *title = "PS2 Game");
    bool syncCoreSubsystems();
    bool loadELF(const std::string &elfPath);
    void run();

    void setIopPluginSearchPaths(std::vector<std::filesystem::path> paths);
    [[nodiscard]] ps2x::iop::DebugSnapshot iopDebugSnapshot() const;

    using DebugUiCallback = void (*)(PS2Runtime &runtime, void *userData);
    void setDebugUiCallbacks(DebugUiCallback initCallback,
                             DebugUiCallback drawCallback,
                             DebugUiCallback shutdownCallback,
                             void *userData);

    using RecompiledFunction = void (*)(uint8_t *, R5900Context *, PS2Runtime *);

    enum class GuestBranchKind
    {
        DirectJump,
        DirectCall,
        IndirectJump,
        IndirectCall,
        Return,
    };

    enum class MissingFunctionPolicy : uint32_t
    {
        // Strict mode for tests/CI: log the bad target and request the runtime to stop.
        Stop = 0,

        // Debug mode: log once, leave ctx->pc on the bad target, and let the caller unwind.
        ContinueToTarget = 1,

        // Debug mode: same as ContinueToTarget, but triggers a debugger break once on MSVC.
        BreakOnce = 2,

        // Escape hatch only: skip missing calls by returning to fallthrough (it can hide guest bugs)
        SkipCallDebug = 3,
    };

    bool replaceFunction(uint32_t address, RecompiledFunction func);
    // TODO remove this later need to update all tests
    bool registerFunction(uint32_t address, RecompiledFunction func);
    RecompiledFunction lookupFunction(uint32_t address);
    bool hasFunction(uint32_t address) const;
    // COP0 Count as the guest sees it: the EE core clock (294.912 MHz) derived from the host
    // steady clock. `mfc0 Count` is recompiled as a plain read of ctx->cop0_count, so the field is
    // refreshed at every syscall, guest-branch dispatch and scheduler switch-in (SOCOM's SCE-RT
    // timers, e.g. the SCERT send interval, are built on it).
    static uint32_t guestCop0Count();
    static void refreshCop0Count(R5900Context *ctx);
    bool dispatchGuestBranch(uint8_t *rdram,
                             R5900Context *ctx,
                             uint32_t targetPc,
                             uint32_t sourcePc,
                             uint32_t fallthroughPc,
                             GuestBranchKind kind,
                             const char *debugName);
    void reportMissingFunction(uint8_t *rdram,
                               R5900Context *ctx,
                               uint32_t targetPc,
                               uint32_t sourcePc,
                               GuestBranchKind kind,
                               const char *debugName);
    void setMissingFunctionPolicy(MissingFunctionPolicy policy);
    MissingFunctionPolicy missingFunctionPolicy() const;
    void resetMissingFunctionReportOnce();

    static const IoPaths &getIoPaths();
    static void setIoPaths(const IoPaths &paths);
    static void configureIoPathsFromElf(const std::string &elfPath);

    void SignalException(R5900Context *ctx, PS2Exception exception);

    void executeVU0Microprogram(uint8_t *rdram, R5900Context *ctx, uint32_t address);
    void vu0StartMicroProgram(uint8_t *rdram, R5900Context *ctx, uint32_t address);

public:
    void handleSyscall(uint8_t *rdram, R5900Context *ctx);
    void handleSyscall(uint8_t *rdram, R5900Context *ctx, uint32_t encodedSyscallId);
    void handleBreak(uint8_t *rdram, R5900Context *ctx);

    void handleTrap(uint8_t *rdram, R5900Context *ctx);
    void handleTLBR(uint8_t *rdram, R5900Context *ctx);
    void handleTLBWI(uint8_t *rdram, R5900Context *ctx);
    void handleTLBWR(uint8_t *rdram, R5900Context *ctx);
    void handleTLBP(uint8_t *rdram, R5900Context *ctx);
    void clearLLBit(R5900Context *ctx);
    void noteLoadedImageEnd(uint32_t maxLoadedRdramEnd);
    void configureGuestHeap(uint32_t guestBase, uint32_t guestLimit = PS2_RAM_SIZE);
    uint32_t guestMalloc(uint32_t size, uint32_t alignment = 16u);
    uint32_t guestCalloc(uint32_t count, uint32_t size, uint32_t alignment = 16u);
    uint32_t guestRealloc(uint32_t guestAddr, uint32_t newSize, uint32_t alignment = 16u);
    void guestFree(uint32_t guestAddr);
    uint32_t guestHeapBase() const;
    uint32_t guestHeapEnd() const;
    uint32_t guestHeapLimit() const;
    uint32_t reserveAsyncCallbackStack(uint32_t size, uint32_t alignment = 16u);

    void drainCompletedDmacHandlers(uint8_t *rdram);

    void requestStop();
    bool isStopRequested() const;

    // Sprint 17 Task Q2 (D3): LoadExecPS2 as an in-process restart of the guest. Leaving SOCOM Online is the
    // game's own LoadExecPS2("cdrom0:\SCUS_972.75;1", 3, {"--menu_state", "dlgAfterErrorReboot.rdr", ""})
    // (docs/research/78-back-to-the-main-menu.md); on the console the kernel reloads the ELF with those
    // arguments, and this runtime used to exit 74 instead.
    struct GuestRestartRequest
    {
        std::string elfPath;               // the host file the loader reloads (the ELF the runtime booted)
        std::string guestPath;             // what the guest asked for ("cdrom0:\SCUS_972.75;1"): the crt0's argv[0]
        std::vector<std::string> argv;     // the request's own arguments: the crt0's argv[1..]
    };
    // Called on the game thread (the LoadExecPS2 syscall): records the request, logs it, and stops the
    // scheduler so the game thread returns at its next checkpoint. False, and nothing changed, when a request
    // is already pending: two requests before the first completes perform one. An empty guestPath means the
    // ELF's own file name.
    bool requestGuestRestart(std::string elfPath, std::vector<std::string> argv, std::string guestPath = std::string());
    bool guestRestartPending() const;
    GuestRestartRequest guestRestartRequest() const;
    // Called on the loop thread once the game thread has returned: the IOP, SIF and stub state reset, the
    // mixer stopped, the GS reset (the window and its GL context untouched), guest RAM zeroed, the ELF reloaded
    // through loadELF, the kernel's boot-argument block rewritten from the request, the EE kernel state fresh,
    // the EE scheduler reset. The caller respawns the game thread (which resets the scheduler again on its own
    // thread). True when a pending request was performed; false when none was pending or the reload failed
    // (the log says why).
    bool restartGuest();
    uint64_t guestRestartCount() const;
    // The boot arguments a restart set, for SetupThread to copy into the crt0's argument block. A first boot
    // has none and the crt0's block stays what the ELF's bss makes it (argc 0), as it always has.
    bool hasBootArguments() const;
    GuestRestartRequest bootArguments() const;

    EeScheduler &eeScheduler();
    const EeScheduler &eeScheduler() const;
    void postEeEvent(EeEvent event);
    bool eeCheckpointDue(uint32_t cycles = 32u) noexcept;
    // Set whenever a generated function returns to the host without having finished (scheduler
    // checkpoint, non-call transfer, missing target); cleared by the scheduler before each dispatch.
    // dispatchGuestBranch uses it to tell "callee returned" from "callee unwound", which the
    // pc-based check cannot do when a recursive callee unwinds at its own entry pc.
    void markDispatchUnwind() noexcept { m_dispatchUnwinding = true; }
    void clearDispatchUnwind() noexcept { m_dispatchUnwinding = false; }
    bool dispatchUnwinding() const noexcept { return m_dispatchUnwinding; }
    [[noreturn]] void eeWaitVSyncTicks(uint32_t ticks, uint32_t resumePc);

    struct EeExitHandlerRegistration
    {
        uint32_t function = 0;
        uint32_t argument = 0;
    };
    void addEeExitHandler(int threadId, uint32_t function, uint32_t argument);
    std::vector<EeExitHandlerRegistration> takeEeExitHandlers(int threadId);
    void removeEeExitHandlers(int threadId);
    bool findEeSyscallOverride(uint32_t syscallNumber, uint32_t &handler) const;
    void setEeSyscallOverride(uint8_t *rdram, uint32_t syscallNumber, uint32_t handler);
    void initializeEeKernelState(uint8_t *rdram);
    // True the first time this (syscall, handler) pair is seen to be unrunnable on THIS runtime,
    // so the dispatcher's diagnostic prints once per pair per guest-kernel lifetime rather than
    // once per process. Capped, so a guest registering many distinct handlers cannot grow it
    // without bound; past the cap it answers false and stays quiet.
    bool noteUnrunnableSyscallOverride(uint32_t syscallNumber, uint32_t handler);

    uint8_t Load8(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr);
    uint16_t Load16(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr);
    uint32_t Load32(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr);
    uint64_t Load64(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr);
    __m128i Load128(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr);

    void Store8(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr, uint8_t value);
    void Store16(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr, uint16_t value);
    void Store32(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr, uint32_t value);
    void Store64(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr, uint64_t value);
    void Store128(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr, __m128i value);
    void kickGifDmaChainFromMMIO(uint8_t *rdram,
                                 R5900Context *ctx,
                                 uint32_t dPcrValue,
                                 uint32_t dStatValue,
                                 uint32_t tadr,
                                 uint32_t chcr);

    static inline bool isSpecialAddress(uint32_t addr)
    {
        return Ps2IsSpecialAddress(addr);
    }

public:
    inline R5900Context &cpu() { return m_cpuContext; }
    inline const R5900Context &cpu() const { return m_cpuContext; }

    inline PS2Memory &memory() { return m_memory; }
    inline const PS2Memory &memory() const { return m_memory; }

    inline GS &gs() { return m_gs; }
    inline const GS &gs() const { return m_gs; }
    inline GifArbiter &gifArbiter() { return m_gifArbiter; }
    inline const GifArbiter &gifArbiter() const { return m_gifArbiter; }
    inline VU1Interpreter &vu0() { return m_vu0; }
    inline const VU1Interpreter &vu0() const { return m_vu0; }
    inline VU1Interpreter &vu1() { return m_vu1; }
    inline const VU1Interpreter &vu1() const { return m_vu1; }

    inline PS2AudioBackend &audioBackend() { return m_audioBackend; }
    inline const PS2AudioBackend &audioBackend() const { return m_audioBackend; }
    inline PSPadBackend &padBackend() { return m_padBackend; }
    inline const PSPadBackend &padBackend() const { return m_padBackend; }

private:
    struct GuestHeapBlock
    {
        uint32_t addr = 0;
        uint32_t size = 0;
        bool free = true;
    };

    static uint32_t alignGuestHeapValue(uint32_t value, uint32_t alignment);
    static bool isGuestHeapAlignmentValid(uint32_t alignment);
    static uint32_t normalizeGuestHeapAlignment(uint32_t alignment);
    uint32_t clampGuestHeapBase(uint32_t guestBase) const;
    uint32_t clampGuestHeapLimit(uint32_t guestLimit) const;
    void resetGuestHeapLocked(uint32_t guestBase, uint32_t guestLimit);
    void ensureGuestHeapInitializedLocked();
    int32_t findGuestHeapBlockIndexLocked(uint32_t guestAddr) const;
    uint32_t allocateGuestBlockLocked(uint32_t size, uint32_t alignment);
    void freeGuestBlockLocked(uint32_t guestAddr);
    void coalesceGuestHeapLocked();
    void HandleIntegerOverflow(R5900Context *ctx);

    [[nodiscard]] ps2x::iop::RpcAbi selectIopRpcAbi(const ps2x::iop::RpcAbiRequest &request) const;
    [[nodiscard]] ps2x::iop::RpcResult handleIopRpc(uint8_t *rdram, R5900Context *ctx, ps2x::iop::RpcRequest request);
    void notifyIopSifTransfer(uint8_t *rdram, const ps2x::iop::SifTransfer &transfer);
    void resetIop();
    // The guest-kernel prologue run() performs before the game thread starts, shared with restartGuest():
    // the SIF, IOP, audio, MPEG and stub state, the EE kernel state, the boot registers.
    void prepareGuestBoot();
    void resetCpuContext();

    friend class PS2IopTransport;
    friend class EeScheduler;

private:
    PS2Memory m_memory;
    GifArbiter m_gifArbiter;
    GS m_gs;
    std::unique_ptr<PS2IopHostAdapter> m_iopHost;
    std::unique_ptr<ps2x::iop::IopSubsystem> m_iopSubsystem;
    PS2AudioBackend m_audioBackend;
    PSPadBackend m_padBackend;
    VU1Interpreter m_vu0{VU1Interpreter::Unit::VU0};
    VU1Interpreter m_vu1{VU1Interpreter::Unit::VU1};
    R5900Context m_cpuContext;
    std::unique_ptr<EeScheduler> m_eeScheduler;
    mutable std::mutex m_eeKernelStateMutex;
    std::unordered_map<int, std::vector<EeExitHandlerRegistration>> m_eeExitHandlers;
    std::unordered_map<uint32_t, uint32_t> m_eeSyscallOverrides;
    std::unordered_set<uint32_t> m_eeSyscallMirrorAddresses;
    // (syscall << 32) | handler pairs already reported as unrunnable; see
    // noteUnrunnableSyscallOverride. Guarded by m_eeKernelStateMutex.
    std::unordered_set<uint64_t> m_unrunnableSyscallOverrides;
    static constexpr size_t kMaxUnrunnableSyscallOverridesReported = 64u;
    mutable std::mutex m_guestHeapMutex;
    mutable std::mutex m_asyncCallbackStackMutex;
    std::vector<GuestHeapBlock> m_guestHeapBlocks;
    uint32_t m_guestHeapBase = 0x00100000u;
    uint32_t m_guestHeapEnd = 0x00100000u;
    uint32_t m_guestHeapLimit = PS2_RAM_SIZE;
    uint32_t m_guestHeapSuggestedBase = 0x00100000u;
    bool m_guestHeapConfigured = false;
    uint32_t m_asyncCallbackStackFloor = 0x01F00000u;
    uint32_t m_asyncCallbackStackTop = PS2_RAM_SIZE;

    std::atomic<uint32_t> m_missingFunctionPolicy{static_cast<uint32_t>(MissingFunctionPolicy::ContinueToTarget)};
    std::atomic<bool> m_missingFunctionReported{false};
    bool m_dispatchUnwinding = false;
    std::atomic<bool> m_stopRequested{false};
    // Sprint 17 Q2: the pending restart (written on the game thread, performed on the loop thread) and the
    // boot arguments the last restart left for SetupThread. Guarded by m_guestRestartMutex.
    mutable std::mutex m_guestRestartMutex;
    bool m_guestRestartPending = false;
    GuestRestartRequest m_guestRestartRequest;
    bool m_bootArgumentsSet = false;
    GuestRestartRequest m_bootArguments;
    std::atomic<uint64_t> m_guestRestartCount{0};
    // The ELF whose game overrides this runtime applied (loadELF): an in-process restart of the same ELF keeps
    // them -- the function table is the process's, and the installers that start threads (the pc sampler, the
    // RDRAM dump) or wrap table entries (HLE stats, the sched trace) are not built to run twice.
    std::string m_overridesAppliedFor;
    DebugUiCallback m_debugUiInitCallback = nullptr;
    DebugUiCallback m_debugUiDrawCallback = nullptr;
    DebugUiCallback m_debugUiShutdownCallback = nullptr;
    void *m_debugUiUserData = nullptr;
    bool m_debugUiInitialized = false;

public:
    // The pc stored on EVERY dispatch iteration (EeScheduler.cpp, m_debugPc.store): the pc-sampler prints this as
    // dpc= because m_cpuContext.pc is only copied out every 4096 dispatches (research/29 section 4 item 4).
    uint32_t debugPc() const { return m_debugPc.load(std::memory_order_relaxed); }
    std::atomic<uint32_t> m_debugPc{0};
    std::atomic<uint32_t> m_debugRa{0};
    std::atomic<uint32_t> m_debugSp{0};
    std::atomic<uint32_t> m_debugGp{0};

private:
    struct LoadedModule
    {
        std::string name;
        uint32_t baseAddress;
        size_t size;
        bool active;
    };

    std::vector<LoadedModule> m_loadedModules;
    uint8_t *m_boundRdram = nullptr;
    uint8_t *m_boundGSVram = nullptr;

public:
    // Sprint 11 Task 8b: the EE stub subsystems' mutable state. It used to be defined in an
    // anonymous namespace in Kernel/Stubs/Helpers/Support.h, which gave every translation unit
    // that included it a private copy (docs/KNOWN.md #4, the reverted 955539c). It now belongs to
    // the runtime the stub was called with, the way the Cucumber fork holds it, so that two
    // PS2Runtime instances in one process share none of it and Task 8c's save-state writer can
    // enumerate it per runtime. Each object is created with the runtime and lives as long as it.
    // A stub reached with no runtime falls back to one process-wide instance of each -- see the
    // ps2_stubs::*RuntimeStateFor() helpers in Kernel/Stubs/Helpers/.
    ps2_stubs::StubLogRuntimeState &stubLogRuntimeState();
    const ps2_stubs::StubLogRuntimeState &stubLogRuntimeState() const;
    ps2_stubs::DmaRuntimeState &dmaRuntimeState();
    const ps2_stubs::DmaRuntimeState &dmaRuntimeState() const;
    ps2_stubs::GsRuntimeState &gsRuntimeState();
    const ps2_stubs::GsRuntimeState &gsRuntimeState() const;
    ps2_stubs::LibCRuntimeState &libcRuntimeState();
    const ps2_stubs::LibCRuntimeState &libcRuntimeState() const;
    ps2_stubs::CdRuntimeState &cdRuntimeState();               // issue #51: Support.h's CD group
    const ps2_stubs::CdRuntimeState &cdRuntimeState() const;
    ps2_stubs::IopHeapRuntimeState &iopHeapRuntimeState();     // issue #51: Support.h's g_iopHeapNext
    const ps2_stubs::IopHeapRuntimeState &iopHeapRuntimeState() const;

    // Every stub subsystem's state back to a freshly constructed runtime's. Nothing in the guest
    // path calls this -- sceDmaReset resets the DMA object alone -- it is the whole-machine entry
    // point the tests and a save-state restore (Task 8c) need.
    void resetStubRuntimeState();

private:
    std::unique_ptr<ps2_stubs::StubLogRuntimeState> m_stubLogRuntimeState;
    std::unique_ptr<ps2_stubs::DmaRuntimeState> m_dmaRuntimeState;
    std::unique_ptr<ps2_stubs::GsRuntimeState> m_gsRuntimeState;
    std::unique_ptr<ps2_stubs::LibCRuntimeState> m_libcRuntimeState;
    std::unique_ptr<ps2_stubs::CdRuntimeState> m_cdRuntimeState;
    std::unique_ptr<ps2_stubs::IopHeapRuntimeState> m_iopHeapRuntimeState;
};

